<script setup lang="ts">
import { computed } from 'vue'
import type { Valuation } from '../api'
import { number, reasonLabel, date } from '../utils'
import StatusBadge from './StatusBadge.vue'
import LineChart from './LineChart.vue'
import JsonDetails from './JsonDetails.vue'
const props = defineProps<{ report: Valuation }>()
const r = computed(() => props.report.result)
const sensitivity = computed(() => !r.value ? [] : Array.from({length:11},(_,i) => ({ x: number(i/10,1), y: i/10*r.value!.b_success+(1-i/10)*r.value!.b_failure-r.value!.fixed_cost, reason: '固定收益与成本，改变假设履约概率 q' })))
</script>
<template><section class="panel value-result"><div class="panel-heading"><div><p class="eyebrow">CONDITIONAL RESEARCH VALUE</p><h2>风险调整后的预期净价值</h2><p class="muted small">{{ report.asset_id }} / {{ report.asset_version }} · {{ report.task_id }}</p></div><StatusBadge :value="report.status"/></div><p class="footnote">评估时点：{{ date(report.as_of_time) }} · 信用来源：{{ r?.credit_origin ?? report.delivery_reliability?.result?.origin ?? '见完整报告' }}</p><div v-if="report.status === 'NOT_EVALUATED' || !r" class="notice warning" data-testid="not-evaluated"><strong>NOT_EVALUATED · 无精确测量，拒绝生成估值</strong><p>{{ reasonLabel(report.reason ?? '') }}</p><p>不会借用相似资产、其他版本或内容哈希的结果。</p></div><template v-else><div class="value-highlight" :class="{negative:r.value <= 0}"><span class="big-value">{{ number(r.value,3) }}</span><span>假设损失单位 · 许可价格之前</span><p>{{ r.value <= 0 ? '保留负收益：当前条件下可能不值得购买' : '正条件价值也不能独立构成采购授权' }}</p></div><div class="metric-grid four"><div class="metric"><span>成功交付条件收益 B_success</span><strong>{{ number(r.b_success) }}</strong></div><div class="metric"><span>失败情景收益 B_failure</span><strong>{{ number(r.b_failure) }}</strong></div><div class="metric"><span>固定接入成本 C_fixed</span><strong>{{ number(r.fixed_cost) }}</strong></div><div class="metric"><span>未来履约概率 q</span><strong>{{ number(r.q,4) }}</strong></div></div><div class="formula">W = {{ number(r.q,4) }} × {{ number(r.b_success) }} + (1 − {{ number(r.q,4) }}) × {{ number(r.b_failure) }} − {{ number(r.fixed_cost) }} = <b>{{ number(r.value) }}</b></div><div class="two-column"><section><h3>价值组成</h3><table><tbody><tr><th>成功分支 q × B_success</th><td>{{ number(r.q*r.b_success) }}</td></tr><tr><th>失败分支 (1−q) × B_failure</th><td>{{ number((1-r.q)*r.b_failure) }}</td></tr><tr><th>固定成本扣减</th><td>{{ number(-r.fixed_cost) }}</td></tr><tr><th>风险调整前（q=1）</th><td>{{ number(r.b_success-r.fixed_cost) }}</td></tr></tbody></table><h3>测量与不确定性</h3><dl class="details-grid"><dt>任务边际效用 ΔLog Loss</dt><dd>{{ number(report.conditional_utility?.result?.delta_utility ?? report.conditional_utility?.result?.delta_log_loss ?? report.conditional_utility?.result?.delta_logloss,6) }}</dd><dt>模型状态</dt><dd><StatusBadge :value="r.model_status"/></dd><dt>固定 q 任务重采样区间</dt><dd>[{{ number(r.conditional_low) }}, {{ number(r.conditional_high) }}]</dd><dt>信用端点压力范围</dt><dd>[{{ number(r.credit_sensitivity_low) }}, {{ number(r.credit_sensitivity_high) }}]</dd><dt>有效合同数</dt><dd>{{ r.credit_n_history }}</dd></dl></section><section><LineChart :points="sensitivity" title="履约概率 q 的压力敏感性" unit="横轴 q（0–1）；纵轴 W / 假设损失单位"/><table><thead><tr><th>信用压力情景</th><th>q</th><th>W / 假设损失单位</th></tr></thead><tbody><tr v-for="[label,q] in [['模型条件下端点',r.q_lower],['点估计',r.q],['模型条件上端点',r.q_upper]]" :key="label"><td>{{ label }}</td><td>{{ number(q,4) }}</td><td>{{ number(q*r.b_success+(1-q)*r.b_failure-r.fixed_cost) }}</td></tr></tbody></table></section></div><div class="notice warning"><strong>区间不构成已校准商业风险保证</strong><p>固定 q 的任务重采样区间不包含信用、经济参数和分布漂移不确定性；信用端点压力范围是敏感性分析。</p><ul v-if="r.reasons?.length"><li v-for="reason in r.reasons" :key="reason">{{ reasonLabel(reason) }}</li></ul></div></template><JsonDetails :data="report" title="核对完整价值报告与测量来源"/></section></template>
